using System.Numerics;
using TI5X.Avalonia.Core;

namespace TI5X.Core.Tests;

/// <summary>
/// Consistency triad for the TI-59 printer (TMC0251 / PC-100A):
///   1. the hand port (Ti59PrintMachine, no Dafny types) must match the
///      Dafny-verified translation (Ti59PrintCore.cs compiled from
///      ti59-dafny/dfy/TI59/Print.dfy, itself proven faithful to the C
///      oracle print.c by the ti59-dafny differential corpus 12/12),
///   2. the ml01print oracle tape fixture (ti59-dafny/tests/traces,
///      regenerated by gen-traces.sh + compare-trace.py, 100% bit-exact)
///      must be reproducible through the port's font/buffer/Print mechanics,
///   3. the app-level print register mapping (Op 1-5) and the listing
///      mnemonics must follow the empirically verified rules (see
///      PrinterEngine.PrintRegisterChar / ListMnemonic).
/// Do not "fix" a failing equality here - run scripts/gen-core.sh and
/// scripts/gen-print.sh first; the verified model is the source of truth.
/// </summary>
public class Ti59PrintModelTests
{
    // ---------------------------------------------------------------
    // Dafny-translation shims
    // ---------------------------------------------------------------

    private static string Rus(Dafny.ISequence<Dafny.Rune> s)
        => new string(s.Select(r => (char)r.Value).ToArray());

    private static TI59__Bus._IBus GenBus(ushort irg, ushort ext)
        => TI59__Bus.Bus.create(
            ext, irg,
            Dafny.Sequence<byte>.Empty,
            new Dafny.Rune(' '), false, false,
            0, new BigInteger(15), false, BigInteger.Zero, BigInteger.Zero);

    private record struct Op(string Kind, int Code);

    private static (int Irg, int Ext) OpToBus(Op op) => op.Kind switch
    {
        "LoadChar" => (0x0A68, op.Code << 3),
        "LoadFunc" => (0x0A78, op.Code << 3),
        "Step" => (0x0A98, 0),
        "Clear" => (0x0A88, 0),
        "Print" => (0x0AA8, 0),
        _ => (0x0AB8, 0), // Advance
    };

    private static void PortStep(Ti59PrintMachine m, Op op)
    {
        switch (op.Kind)
        {
            case "LoadChar": m.LoadChar((byte)op.Code); break;
            case "LoadFunc": m.LoadFunc((byte)op.Code); break;
            case "Step": m.Step(); break;
            case "Clear": m.Clear(); break;
            case "Print": m.PrintLine(); break;
            default: m.Advance(); break;
        }
    }

    // Event normalization: both sides produce "kind|head|payload".
    private static string EvText(TI59__Events._ITi59Event e) => e switch
    {
        TI59__Events.Ti59Event_EvPrintChar c
            => $"Char|{c._head}|{(char)c._ch.Value}",
        TI59__Events.Ti59Event_EvPrintFunc f
            => $"Func|{f._head}|{Rus(f._s)}",
        TI59__Events.Ti59Event_EvPrintNotFound n
            => $"NotFound|{n._head}|{n._code}",
        TI59__Events.Ti59Event_EvPrintClear c
            => $"Clear|{c._head}|{Rus(c._buf)}",
        TI59__Events.Ti59Event_EvPrint p
            => $"Print|{p._head}|{Rus(p._buf)}",
        _ => throw new InvalidOperationException("unknown Dafny print event"),
    };

    private static string EvText(Ti59PrintEvent e)
        => $"{e.Kind}|{e.Head}|{(e.Kind == Ti59PrintEventKind.NotFound
                ? e.Code.ToString() : e.Str)}";

    // Deterministic op plan: full LoadChar/LoadFunc sweeps + a mixed
    // pseudo-random run, so every PrintStep branch and both head wraps
    // (the whole 0..19 cycle) get exercised.
    private static List<Op> OpPlan()
    {
        var ops = new List<Op>
        {
            new("Print", 0), new("Advance", 0),
            new("LoadChar", 0), new("LoadChar", 63),
            new("LoadFunc", 0), new("LoadFunc", 127),
            new("Step", 0), new("Clear", 0),
        };
        uint s = 123456789;
        for (int i = 0; i < 400; ++i)
        {
            s = s * 1664525 + 1013904223;
            var sel = (s >> 16) % 6;
            ops.Add(sel switch
            {
                0 => new Op("LoadChar", (int)((s >> 8) & 63)),
                1 => new Op("LoadFunc", (int)((s >> 8) & 127)),
                2 => new Op("Step", 0),
                3 => new Op("Clear", 0),
                4 => new Op("Print", 0),
                _ => new Op("Advance", 0),
            });
        }
        return ops;
    }

    // ---------------------------------------------------------------
    // 1. Tables: port == Dafny-verified translation
    // ---------------------------------------------------------------

    [Test]
    public async Task Font_tables_match_Dafny_verified_model()
    {
        var genFont = TI59__Print.__default.PrintFont().Select(r => (char)r.Value).ToArray();
        var genSr60 = TI59__Print.__default.PrintFontSr60().Select(r => (char)r.Value).ToArray();

        await Assert.That(Ti59PrintMachine.FontTable.Length).IsEqualTo(64);
        for (int i = 0; i < 64; ++i)
        {
            if (Ti59PrintMachine.FontTable[i] != genFont[i])
            {
                await Assert.That(Ti59PrintMachine.FontTable[i]).IsEqualTo(genFont[i]);
            }
        }
        await Assert.That(Ti59PrintMachine.FontSr60Table.Length).IsEqualTo(64);
        for (int i = 0; i < 64; ++i)
        {
            if (Ti59PrintMachine.FontSr60Table[i] != genSr60[i])
            {
                await Assert.That(Ti59PrintMachine.FontSr60Table[i]).IsEqualTo(genSr60[i]);
            }
        }

        // print.c properties relied upon elsewhere: all 64 chars unique,
        // blank at index 0 (reversed font map is collision-free).
        await Assert.That(Ti59PrintMachine.FontTable.Distinct().Count()).IsEqualTo(64);
        await Assert.That(Ti59PrintMachine.FontTable[0]).IsEqualTo(' ');

        var genFuncs = TI59__Print.__default.PrintFuncTable().ToList();
        await Assert.That(Ti59PrintMachine.FuncTable.Length).IsEqualTo(39);
        for (int i = 0; i < 39; ++i)
        {
            var (portCode, portStr) = Ti59PrintMachine.FuncTable[i];
            var g = genFuncs[i];
            if (portCode != g.dtor__0 || portStr != Rus(g.dtor__1))
            {
                await Assert.That(portStr).IsEqualTo(Rus(g.dtor__1));
            }
        }
    }

    // ---------------------------------------------------------------
    // 2. Op sweep: port == Dafny-verified model (state + events)
    // ---------------------------------------------------------------

    [Test]
    public async Task Hand_port_matches_Dafny_verified_model_over_op_sweep()
    {
        var ops = OpPlan();
        var gen = TI59__Print.__default.PrintInit();
        var port = new Ti59PrintMachine();
        var genEvents = new List<string>();

        for (int step = 0; step < ops.Count; ++step)
        {
            var (irg, ext) = OpToBus(ops[step]);
            var r = TI59__Print.__default.PrintStep(
                gen, GenBus((ushort)irg, (ushort)ext),
                new BigInteger(15), false);
            gen = r.dtor__0;
            genEvents.AddRange(r.dtor__1.Select(EvText));
            PortStep(port, ops[step]);

            var genBuf = Rus(gen.dtor_buffer);
            var genHead = (int)gen.dtor_head;
            var genTape = gen.dtor_tape.Select(Rus).ToList();

            if (port.BufferString != genBuf
                || port.Head != genHead
                || port.Tape.Count != genTape.Count
                || (genTape.Count > 0 && port.Tape[genTape.Count - 1] != genTape[genTape.Count - 1])
                || port.Events.Count != genEvents.Count
                || (genEvents.Count > 0
                    && EvText(port.Events[port.Events.Count - 1]) != genEvents[genEvents.Count - 1]))
            {
                await Assert.That(
                        $"op #{step} {ops[step].Kind}({ops[step].Code}): port " +
                        $"buf='{port.BufferString}' head={port.Head} " +
                        $"tape={port.Tape.Count}:'{port.Tape.LastOrDefault()}' " +
                        $"ev={port.Events.Count}:" +
                        $"'{(port.Events.Count > 0 ? EvText(port.Events[^1]) : "-")}'")
                    .IsEqualTo(
                        $"op #{step} {ops[step].Kind}({ops[step].Code}): dafny " +
                        $"buf='{genBuf}' head={genHead} " +
                        $"tape={genTape.Count}:'{genTape.LastOrDefault()}' " +
                        $"ev={genEvents.Count}:" +
                        $"'{(genEvents.Count > 0 ? genEvents[^1] : "-")}'");
            }
        }

        // The sweep must actually exercise the branches (>= 400 mixed ops,
        // non-empty tape, some events, and the head has wrapped both ways).
        await Assert.That(ops.Count >= 400).IsTrue();
        await Assert.That(port.Tape.Count > 50).IsTrue();
        await Assert.That(port.Events.Count > 200).IsTrue();
    }

    // ---------------------------------------------------------------
    // 3. Oracle tape fixture (ml01print) reproduced through the model
    // ---------------------------------------------------------------

    private static readonly string FixturePath =
        Path.Combine(AppContext.BaseDirectory, "fixtures", "ml01print.tape.txt");

    private static List<string> LoadOracleTapeLines()
    {
        // File lines = "|      " (7 chars: pipe + 6 spaces) + 20-char model
        // row, as written by the ti59d display_print / the runner.
        return File.ReadAllLines(FixturePath)
            .Where(l => l.Length > 0)
            .Select(l => l.TrimEnd('\r').Substring(7))
            .ToList();
    }

    private static void PrintText(Ti59PrintMachine m, string text20)
    {
        m.Clear();
        for (int i = text20.Length - 1; i >= 0; --i)
        {
            m.LoadChar(PrinterEngine.CharToFontIndex(text20[i]));
        }
        m.PrintLine();
    }

    [Test]
    public async Task Oracle_tape_fixture_is_reproduced_by_the_model()
    {
        var oracle = LoadOracleTapeLines();
        // gen-traces produced (ML-01 diagnostic + PRINT through the ROM):
        // "              MASTER", "          1.        ", "          1.        "
        await Assert.That(oracle.Count).IsEqualTo(3);
        await Assert.That(oracle[0].TrimEnd()).IsEqualTo("              MASTER");

        var m = new Ti59PrintMachine();
        foreach (var line in oracle)
        {
            PrintText(m, line);
        }

        await Assert.That(m.Tape.Count).IsEqualTo(oracle.Count);
        for (int i = 0; i < oracle.Count; ++i)
        {
            if (m.Tape[i] != oracle[i])
            {
                await Assert.That(m.Tape[i]).IsEqualTo(oracle[i]);
            }
        }
    }

    [Test]
    public async Task Generated_model_reproduces_the_oracle_tape_too()
    {
        var oracle = LoadOracleTapeLines();
        var gen = TI59__Print.__default.PrintInit();
        foreach (var line in oracle)
        {
            gen = TI59__Print.__default.PrintStep( // clear
                gen, GenBus(0x0A88, 0), new BigInteger(15), false).dtor__0;
            for (int i = line.Length - 1; i >= 0; --i)
            {
                var code = Array.FindIndex(
                    Ti59PrintMachine.FontTable, c => c == line[i]);
                gen = TI59__Print.__default.PrintStep( // load char
                    gen, GenBus(0x0A68, (ushort)(code << 3)),
                    new BigInteger(15), false).dtor__0;
            }
            gen = TI59__Print.__default.PrintStep( // print
                gen, GenBus(0x0AA8, 0), new BigInteger(15), false).dtor__0;
        }

        var tape = gen.dtor_tape.Select(Rus).ToList();
        await Assert.That(tape.Count).IsEqualTo(oracle.Count);
        for (int i = 0; i < oracle.Count; ++i)
        {
            if (tape[i] != oracle[i])
            {
                await Assert.That(tape[i]).IsEqualTo(oracle[i]);
            }
        }
    }

    // ---------------------------------------------------------------
    // 4. App-level print register (Op 1-5) mapping
    // ---------------------------------------------------------------

    [Test]
    public async Task Print_register_code_mapping_matches_the_oracle()
    {
        // Empirically verified pairs (oracle PRINT_CHAR events; see
        // PrinterEngine.PrintRegisterChar for the full table + rule).
        // Byte = the 2-digit decimal pair (1-9 digits).
        var cases = new (byte Code, char Ch)[]
        {
            (0,   ' '), (12,  '9'), (16,  'D'), (17,  'E'), (18,  '7'),
            (20,  '-'), (54,  'e'), (56,  ')'), (89,  '8'), (99,  '8'),
            (19,  '8'), (88,  '7'), (98,  '7'), (91,  '8'),
        };
        foreach (var (code, ch) in cases)
        {
            await Assert.That(PrinterEngine.PrintRegisterChar(code)).IsEqualTo(ch);
        }
    }

    [Test]
    public async Task PrinterEngine_Render_prints_the_register_via_the_model()
    {
        // The oracle ML-01 print-register experiment: X = 1617185456 ->
        // pairs 16,17,18,54,56 into the first five columns, printed as
        // "DE7e)" (oracle stdout: "|      DE7e)").
        var printer = new PrinterEngine();
        var reg = new byte[20];
        reg[0] = 16; reg[1] = 17; reg[2] = 18; reg[3] = 54; reg[4] = 56;
        printer.Render(reg);

        var expected = "DE7e)" + new string(' ', 15);
        await Assert.That(printer.TapeLines.Count).IsEqualTo(1);
        await Assert.That(printer.TapeLines[0]).IsEqualTo(expected);
    }

    [Test]
    public async Task PrinterEngine_basic_paths_flow_through_the_model()
    {
        var printer = new PrinterEngine();

        printer.PrintLine("12");
        await Assert.That(printer.TapeLines[^1]).IsEqualTo("12" + new string(' ', 18));

        printer.Advance();
        await Assert.That(printer.TapeLines[^1]).IsEqualTo(string.Empty);

        printer.Clear();
        await Assert.That(printer.TapeLines.Count).IsEqualTo(0);

        // tape trim at MaxLines. NOTE: uppercase only - the TMC0251 font has
        // no lowercase letters except the math glyphs s/p/e/x/z, and an
        // unmappable char prints blank (authentic behavior).
        for (int i = 0; i < PrinterEngine.MaxLines + 5; ++i)
        {
            printer.PrintLine($"STEP {i}");
        }
        await Assert.That(printer.TapeLines.Count).IsEqualTo(PrinterEngine.MaxLines);
        await Assert.That(printer.TapeLines[0]).IsEqualTo("STEP 5".PadRight(20));
        await Assert.That(printer.TapeLines[^1])
            .IsEqualTo($"STEP {PrinterEngine.MaxLines + 4}".PadRight(20));
    }

    // ---------------------------------------------------------------
    // 5. Listing mnemonics (UI opcode -> print_func, KeyCodeSym fallback)
    // ---------------------------------------------------------------

    [Test]
    public async Task ListMnemonic_uses_print_func_mnemonics_for_mapped_keys()
    {
        var cases = new (int Ui, string Mnem)[]
        {
            (55, " / "), (65, " x "), (85, " + "), (75, " - "), (95, " = "),
            (33, "x^2"), (34, "sX "), (35, "1/x"), (45, "Y^x"), (48, "X|Y"),
            (78, "$+ "), (87, "IF "), (89, "pi "),
        };
        foreach (var (ui, mnem) in cases)
        {
            if (PrinterEngine.ListMnemonic(ui) != mnem)
            {
                await Assert.That(PrinterEngine.ListMnemonic(ui)).IsEqualTo(mnem);
            }
        }
    }

    [Test]
    public async Task ListMnemonic_falls_back_to_KeyCodeSym()
    {
        // Not in the print_func map: digits, LBL, 2ND, " . ", "PRT", "X⇌T".
        var cases = new (int Ui, string Mnem)[]
        {
            (1, " 01"), (21, "2ND"), (76, "LBL"), (93, " . "), (99, "PRT"),
            (32, "X⇌T"),
        };
        foreach (var (ui, mnem) in cases)
        {
            if (PrinterEngine.ListMnemonic(ui) != mnem)
            {
                await Assert.That(PrinterEngine.ListMnemonic(ui)).IsEqualTo(mnem);
            }
        }
    }
}